import XCTest
@testable import TraceLensCore

final class CoreTests: XCTestCase {
    func testMatcherAndSpecificity() throws { let url = try XCTUnwrap(URL(string: "https://api.example.test/payments/create")); XCTAssertTrue(RequestMatcher(host: "api.example.test", pathPrefix: "/payments", methods: [.post]).matches(url, method: .post)); XCTAssertFalse(RequestMatcher(host: "api.example.test", methods: [.get]).matches(url, method: .post)); XCTAssertGreaterThan(RequestMatcher(host: "api.example.test", pathPrefix: "/payments").specificity, RequestMatcher(host: "api.example.test").specificity) }
    func testRulePriorityAndParser() throws { let url = try XCTUnwrap(URL(string: "https://api.example.test/api/v2/demo/payment-service/create")); let engine = ObservationRuleEngine(); let configured = ObservationRule.host("api.example.test", capture: .full); let next = ObservationRule.host("api.example.test", capture: .none, origin: .nextRequest); XCTAssertEqual(engine.captureLevel(url: url, method: .post, configured: [configured], session: [], next: [next], defaultCapture: .metadata), .none); let parsed = EndpointParser(strategy: .serviceAfterPathPrefix("/api/v2/demo"), aliases: ["payment-service": "Payments"]).parse(url); XCTAssertEqual(parsed.technicalService, "payment-service"); XCTAssertEqual(parsed.displayService, "Payments"); XCTAssertEqual(parsed.endpoint, "/create"); let versionedURL = try XCTUnwrap(URL(string: "https://api.example.test/v2/sicredi/payments/orders")); let versioned = EndpointParser(strategy: .serviceAtPathIndex(2), aliases: ["payments": "Pagamentos"]).parse(versionedURL); XCTAssertEqual(versioned.displayService, "Pagamentos"); XCTAssertEqual(versioned.endpoint, "/orders") }
    func testSensitiveData() { XCTAssertEqual(SensitiveData.value("secret", key: "Authorization", policy: .redacted), "••••••••"); XCTAssertEqual(SensitiveData.value("ok", key: "Accept", policy: .redacted), "ok") }
}
